package com.italiano2774.nativeapp;
import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.core.content.ContextCompat;import androidx.fragment.app.Fragment;import java.util.*;
public class PronunciationMapFragment extends Fragment{
 private static class Skill{String key,name,tip;Skill(String k,String n,String t){key=k;name=n;tip=t;}}
 private final List<Skill> skills=Arrays.asList(new Skill("pron_double","双辅音","ll / tt / ss / nn / pp"),new Skill("pron_r","R / RR","单 r 与强 rr"),new Skill("pron_gli","GLI /ʎ/","figlio、famiglia"),new Skill("pron_gn","GN /ɲ/","bagno、signore"),new Skill("pron_hard_soft","硬音 / 软音","ce/che、ci/chi、ge/ghe"));
 @Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup c,@Nullable Bundle s){View v=i.inflate(R.layout.fragment_pronunciation_map,c,false);ProgressStore p=new ProgressStore(requireContext());LinearLayout box=v.findViewById(R.id.container_pm_skills);int total=0,used=0;String weakest="尚未训练";int weak=101;for(Skill sk:skills){int a=p.auxiliaryAttempts(sk.key),acc=p.auxiliaryAccuracy(sk.key);if(a>0){total+=acc;used++;if(acc<weak){weak=acc;weakest=sk.name;}}LinearLayout row=new LinearLayout(requireContext());row.setOrientation(LinearLayout.VERTICAL);row.setPadding(0,dp(8),0,dp(10));TextView t=new TextView(requireContext());t.setText(sk.name+"  "+(a==0?"未测试":acc+"%")+" · "+sk.tip);t.setTextSize(14);t.setTextColor(ContextCompat.getColor(requireContext(),R.color.text_primary));t.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);row.addView(t);ProgressBar b=new ProgressBar(requireContext(),null,android.R.attr.progressBarStyleHorizontal);b.setMax(100);b.setProgress(a==0?0:acc);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,dp(8));bp.topMargin=dp(7);row.addView(b,bp);TextView n=new TextView(requireContext());n.setText("练习 "+a+" 次"+(a>0&&acc<70?" · 建议优先补练":""));n.setTextSize(11);n.setTextColor(ContextCompat.getColor(requireContext(),R.color.text_secondary));LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);np.topMargin=dp(4);row.addView(n,np);box.addView(row);}int avg=used==0?0:Math.round(total/(float)used);((TextView)v.findViewById(R.id.text_pm_summary)).setText("综合 "+avg+"% · 当前最弱："+weakest+" · 已覆盖 "+used+" / "+skills.size()+" 项");v.findViewById(R.id.button_pm_train).setOnClickListener(x->((MainActivity)requireActivity()).openPronunciation());return v;}
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
}
